create extension if not exists pgcrypto;
create type public.epoch_game_status as enum ('WAITING','LOBBY','QUESTION_ACTIVE','QUESTION_ENDED','ROUND_ENDED','LEADERBOARD','GAME_COMPLETED');
create table public.epoch_games (epoch_game_id uuid primary key default gen_random_uuid(), game_name text not null default 'EPOCH FRESHERS CHALLENGE 2026', quiz_code text not null unique, game_status public.epoch_game_status not null default 'WAITING', current_round int not null default 1 check(current_round between 1 and 3), current_question int not null default 0, current_question_id uuid, question_started_at timestamptz, question_ends_at timestamptz, leaderboard_visible boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.epoch_teams (epoch_team_id uuid primary key default gen_random_uuid(), epoch_game_id uuid not null references public.epoch_games(epoch_game_id) on delete cascade, team_name text not null, team_number int not null, unique(epoch_game_id,team_name), unique(epoch_game_id,team_number));
create table public.epoch_players (epoch_player_id uuid primary key default gen_random_uuid(), epoch_game_id uuid not null references public.epoch_games(epoch_game_id) on delete cascade, full_name text not null, branch text not null, fun_fact text not null, favorite_food text not null, hobby text not null, epoch_team_id uuid references public.epoch_teams(epoch_team_id) on delete set null, session_token uuid not null unique default gen_random_uuid(), last_seen_at timestamptz not null default now(), created_at timestamptz not null default now());
create table public.epoch_questions (epoch_question_id uuid primary key default gen_random_uuid(), epoch_game_id uuid not null references public.epoch_games(epoch_game_id) on delete cascade, round_number int not null check(round_number between 1 and 3), question_number int not null check(question_number between 1 and 8), question_text text not null, options jsonb not null check(jsonb_array_length(options)=4), correct_option int not null check(correct_option between 0 and 3), time_limit_seconds int not null default 10 check(time_limit_seconds between 3 and 120), points int not null default 100 check(points>=0), scoring_config jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(epoch_game_id,round_number,question_number));
alter table public.epoch_games add constraint epoch_games_question_fk foreign key(current_question_id) references public.epoch_questions(epoch_question_id) on delete set null;
create table public.epoch_answers (epoch_answer_id uuid primary key default gen_random_uuid(), epoch_game_id uuid not null references public.epoch_games(epoch_game_id) on delete cascade, epoch_question_id uuid not null references public.epoch_questions(epoch_question_id) on delete cascade, epoch_player_id uuid not null references public.epoch_players(epoch_player_id) on delete cascade, selected_option int not null check(selected_option between 0 and 3), is_correct boolean not null, points_awarded numeric(10,2) not null default 0, submitted_at timestamptz not null default now(), unique(epoch_question_id,epoch_player_id));
create index epoch_players_game_idx on public.epoch_players(epoch_game_id); create index epoch_answers_question_idx on public.epoch_answers(epoch_question_id); create index epoch_questions_game_round_idx on public.epoch_questions(epoch_game_id,round_number,question_number);
alter table public.epoch_games enable row level security; alter table public.epoch_teams enable row level security; alter table public.epoch_players enable row level security; alter table public.epoch_questions enable row level security; alter table public.epoch_answers enable row level security;
create policy "epoch game read" on public.epoch_games for select using(true); create policy "epoch teams read" on public.epoch_teams for select using(true); create policy "epoch players read" on public.epoch_players for select using(true);
create function public.epoch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
create trigger epoch_games_updated before update on public.epoch_games for each row execute function public.epoch_updated_at(); create trigger epoch_questions_updated before update on public.epoch_questions for each row execute function public.epoch_updated_at();
alter publication supabase_realtime add table public.epoch_games, public.epoch_players, public.epoch_teams, public.epoch_answers;
